class TradeDesk:
    """Trades between two players: each offers a bundle, held in their own hub; when both
    accept the last offers, the market moves each to the other."""

    def __init__(self, core: MarketCore) -> None:
        self._core = core

    @property
    def mine(self) -> PrivateState:
        return self._core.trades

    def watch(self) -> list[dict[str, Any]]:
        trades: list[dict[str, Any]] = self._core.trades.start()
        return trades

    def unwatch(self) -> None:
        self._core.trades.stop()

    def open(self, player: int | str) -> int:
        """Opens a trade with ``player``; returns its id."""
        trade: int = self._core.change("trade", {"with": int(player)})
        return trade

    def offer(self, trade: int, bundle: dict[str, Any]) -> bool:
        """Offers ``bundle`` (``items`` and ``currency``), held at once. Raises ``insufficient``,
        ``forbidden``, ``finished``."""
        done: bool = self._core.change("offer", {"trade": trade, "bundle": bundle})
        return done

    def accept(self, trade: int) -> str:
        """Returns the trade's state. Raises ``not_ready``, ``finished``."""
        state: str = self._core.change("accept", {"trade": trade})
        return state

    def decline(self, trade: int) -> bool:
        done: bool = self._core.change("decline", {"trade": trade})
        return done
